'use client'

import * as React from 'react'

// The three components a profile is made of. The player is an `identity`, every
// number is a `stat`, and what they have won is an `inventory`. This file
// renders no avatar, no number and no reward of its own.
import { Identity, type IdentityPlayer, type IdentityPresence } from './identity'
import { Stat, type StatProps } from './stat'
import { Inventory, type InventoryProps } from './inventory'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Profile, and `tsc --noEmit` passes on it, so
// the gate cannot catch it.
import './profile.css'

/**
 * Profile: one player's own page.
 *
 * Specimen 4d, in four bands: who they are, the numbers they care about, what
 * they have won, and whatever else the host keeps here. The first three are
 * `identity`, `stat` and `inventory`; the fourth is the host's, because a
 * recent-results list, a privacy row and a sign-out control are the
 * application's business and not this library's.
 *
 * **It loads no profile.** It fetches nothing, signs nobody out, saves no
 * setting and knows no player it was not handed. `player={null}` is the
 * signed-out case and `identity` renders it, which is what a profile tab shows
 * before anybody signs in.
 *
 * A profile holds numbers it does not own: the rank, the streak and the points
 * are each a `stat` carrying its own `data-gs-value`, and the profile carries
 * none, because a container that repeated one of them would leave a host
 * asking which element answered for which number.
 */

export interface ProfileProps extends Omit<React.HTMLAttributes<HTMLElement>, 'children'> {
  /** Whose profile this is. `null` is the signed-out case and renders as one. */
  player: IdentityPlayer | null
  /** Whether they are here now. Passed to `identity`. */
  presence?: IdentityPresence
  /** The line under the name: the club they follow, when they joined. */
  detail?: React.ReactNode
  /**
   * The numbers this player is judged by, in the host's order. Each is passed
   * straight to `stat`, so the kind, the label and the format are the host's.
   */
  stats?: StatProps[]
  /** What they have won. Passed to `inventory`, which owns the empty case. */
  rewards?: InventoryProps['rewards']
  /** What the collection is called. `inventory` announces it. */
  rewardsLabel?: string
  /** The line a player with nothing yet reads. Passed to `inventory`. */
  rewardsEmptyLabel?: string
  /** The player opening a reward. Passed to `inventory`. */
  onReveal?: InventoryProps['onReveal']
  /** The controls beside the name: edit, settings, share. The host's own. */
  actions?: React.ReactNode
  /** The surface's accessible name. */
  label?: string
  /**
   * Everything else the host keeps on this page: recent results, settings rows,
   * sign out. Rendered under the collection, in the host's own markup.
   */
  children?: React.ReactNode
}

/** What the page is called when the host says nothing. */
const DEFAULT_LABEL = 'Profile'

export function Profile({
  player,
  presence,
  detail,
  stats = [],
  rewards,
  rewardsLabel = 'Rewards',
  rewardsEmptyLabel,
  onReveal,
  actions,
  label = DEFAULT_LABEL,
  children,
  className,
  ...rest
}: ProfileProps) {
  return (
    <section
      {...rest}
      className={['gs-profile', className].filter(Boolean).join(' ')}
      data-gs-component="profile"
      aria-label={label}
    >
      <header className="gs-profile__header">
        {/* Identity renders the avatar, the name and the signed-out case, and it
            stays announced: it is the heading of the page rather than
            decoration this file speaks for. */}
        <Identity player={player} presence={presence} size="large">
          {detail === undefined ? null : detail}
        </Identity>
        {actions === undefined || actions === null ? null : (
          <div className="gs-profile__actions" data-gs-scope="profile" data-gs-part="actions">
            {actions}
          </div>
        )}
      </header>

      {stats.length === 0 ? null : (
        // A real list, so a screen reader is told how many numbers there are
        // before reading them. Each stat keeps its own root marker and its own
        // value; the profile carries neither.
        <ul className="gs-profile__stats" data-gs-scope="profile" data-gs-part="list">
          {/* Keyed by position, because a profile may legitimately show two
              numbers of the same kind, two scores from two games for instance,
              and keying on the kind would silently render one of them. The
              host owns the order and this never re-sorts, so the index is
              stable. */}
          {stats.map((stat, at) => (
            <li className="gs-profile__stat" data-gs-scope="profile" data-gs-part="row" key={at}>
              <Stat {...stat} />
            </li>
          ))}
        </ul>
      )}

      {rewards === undefined ? null : (
        // The card grid, specimen 3d's, rather than inventory's default
        // compact cells: a profile's reward is opened where it is shown, and
        // only the card carries the reveal control that `onReveal` reaches.
        <Inventory
          label={rewardsLabel}
          rewards={rewards}
          presentation="card"
          emptyLabel={rewardsEmptyLabel}
          onReveal={onReveal}
        />
      )}

      {children === undefined || children === null ? null : (
        <div className="gs-profile__body" data-gs-scope="profile" data-gs-part="body">
          {children}
        </div>
      )}
    </section>
  )
}

/* Profile. Every value comes from a token; nothing here is a literal colour.

   Specimen 4d draws the page and design/twins/4d.json measures ours against
   it: the surface band with the player centred in it, then the three number
   tiles, the collection and the host's own rows. The level ring and the LV
   badge the drawing puts round the avatar are level-ring's; the profile draws
   the identity at its hero size and no ring of its own.

   Every rule that reaches inside identity or stat is scoped through
   `.gs-profile`, which is the composition rule: a bare `.gs-stat` here would
   tie with stat.css and be decided by bundler order. */

.gs-profile {
  display: flex;
  flex-direction: column;
  gap: var(--gs-space-inset);

  padding-block-end: var(--gs-space-4);
  background: var(--gs-color-background);
  color: var(--gs-color-ink);
  font-family: var(--gs-type-body-font-family);
}

/* -- who they are ---------------------------------------------------------- */
/* The band across the top: the surface, ruled off below, the player centred
   in it with the host's controls under the name. */
.gs-profile__header {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--gs-space-gap);

  padding: var(--gs-space-6) var(--gs-space-4) var(--gs-space-4);
  background: var(--gs-color-surface);
  border-block-end: var(--gs-stroke-ui) solid var(--gs-color-edge);
}

/* Identity stands in a column here: the avatar, then the name, then the line
   under it, all centred. */
.gs-profile__header [data-gs-component='identity'] {
  flex-direction: column;
  align-items: center;
  gap: var(--gs-space-gap);
  min-inline-size: 0;
  text-align: center;
}

.gs-profile__header .gs-identity__avatar {
  box-sizing: border-box;
  border-width: var(--gs-stroke-ui);
  border-color: var(--gs-color-edge);
}

.gs-profile__header .gs-identity__text {
  align-items: center;
  gap: var(--gs-space-2);
}

/* The name shouts where the theme's primary action shouts, and stands on the
   display shadow: one property borrowed from each axis, not an axis
   re-implemented. */
.gs-profile__header .gs-identity__name {
  text-transform: var(--gs-type-action-text-transform-primary, var(--gs-type-action-text-transform, none));
  text-shadow: var(--gs-type-display-shadow, none);
}

/* The line under the name, with the presence in front of it as a small dot,
   which is where the drawing puts it. Identity's own dot is hidden here, not
   removed: the accessible name still carries the word. */
.gs-profile__header .gs-identity__detail {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--gs-space-2);
  font-family: var(--gs-type-eyebrow-font-family);
  font-size: var(--gs-type-eyebrow-font-size);
  font-weight: var(--gs-type-eyebrow-font-weight);
  color: var(--gs-color-ink-secondary);
}

.gs-profile__header [data-gs-presence] .gs-identity__detail::before {
  content: '';
  flex: none;
  box-sizing: border-box;
  inline-size: var(--gs-space-2);
  block-size: var(--gs-space-2);
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-muted);
}

.gs-profile__header [data-gs-presence='online'] .gs-identity__detail::before { background: var(--gs-color-positive); }
.gs-profile__header [data-gs-presence='away'] .gs-identity__detail::before { background: var(--gs-color-warning); }
.gs-profile__header [data-gs-presence='offline'] .gs-identity__detail::before {
  background: none;
  border: var(--gs-stroke-selected) solid var(--gs-color-muted);
}

.gs-profile__header .gs-identity__presence {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  border: 0;
}

.gs-profile__actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: var(--gs-space-2);
}

/* -- the numbers ----------------------------------------------------------- */
/* Three columns, as the drawing lays them: `1fr` is minmax(auto, 1fr), so the
   tile holding a five figure score takes its content width and the other two
   share what is left, which is exactly what the drawing's own grid does with
   #7, x5 and 12,450. A fourth number starts a second row. */
.gs-profile__stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--gs-space-gap);
  margin: 0 var(--gs-space-4);
  padding: 0;
  list-style: none;
}

/* A card: the surface, the ui stroke, the control radius, a 4px shelf, the
   number over its name, centred. */
.gs-profile__stat {
  display: flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;

  padding: var(--gs-space-3) var(--gs-space-2);
  text-align: center;
  background: var(--gs-color-surface);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-control);
  box-shadow: 0 var(--gs-space-1) 0 var(--gs-color-edge);
}

/* The number first and its name under it, which is how the drawing stacks a
   profile tile; stat's own arrangement puts the name above. */
.gs-profile__stat .gs-stat {
  display: grid;
  grid-template-areas: 'value' 'label';
  grid-template-columns: minmax(0, 1fr);
  justify-items: center;
  row-gap: var(--gs-space-1);
  inline-size: 100%;
  min-inline-size: 0;
}

/* The number fits the tile. Three tiles share a phone width, so a tile is
   about 100px inside its padding, and a six figure score at the 22px stat
   size is 110px: it overflowed at five. The size follows the tile's width
   through a container unit, between the figure size and the stat size: six
   tabular Unbounded digits are about 3.7em wide, so 26cqi is the size at
   which six fit the tile's content box, and the tile's padding stays clear. */
.gs-profile__stat {
  container-type: inline-size;
}

.gs-profile .gs-profile__stat .gs-stat .gs-stat__value {
  /* Specificity 0,4,0: stat.css sizes a score at 34px with 0,3,0. */
  font-size: clamp(var(--gs-type-figure-font-size), 26cqi, var(--gs-type-stat-font-size));
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

/* -- the collection and everything the host keeps here --------------------- */
.gs-profile > [data-gs-component='inventory'] {
  margin: 0 var(--gs-space-4);
}

.gs-profile__body {
  display: flex;
  flex-direction: column;
  gap: var(--gs-space-2);
  margin: 0 var(--gs-space-4);
}
